<?php
namespace Portal\Controllers;
use Portal\Models\Usuario;
final class AuthController { public function __construct(private Usuario $usuarios) {} public function loginForm(): void {view('public/login');} public function login(): void {verify_csrf();$email=filter_var(trim($_POST['email']??''),FILTER_VALIDATE_EMAIL);$usuario=$email?$this->usuarios->findByEmail($email):null;if(!$usuario||!password_verify($_POST['senha']??'',$usuario['senha_hash'])){flash('erro','E-mail ou senha inválidos.');header('Location: '.url('login'));exit;}session_regenerate_id(true);$_SESSION['usuario']=['id'=>$usuario['id'],'nome'=>$usuario['nome'],'perfil'=>$usuario['perfil']];header('Location: '.url('admin'));exit;} public function registerForm():void{view('public/register');} public function register():void{verify_csrf();$nome=trim($_POST['nome']??'');$email=filter_var(trim($_POST['email']??''),FILTER_VALIDATE_EMAIL);$senha=$_POST['senha']??'';if(mb_strlen($nome)<3||!$email||strlen($senha)<8){flash('erro','Informe nome, e-mail válido e senha de pelo menos 8 caracteres.');header('Location: '.url('cadastro'));exit;}try{$this->usuarios->create($nome,$email,$senha);flash('sucesso','Cadastro realizado. Faça login para continuar.');}catch(\PDOException){flash('erro','Este e-mail já está cadastrado.');}header('Location: '.url('login'));exit;} public function logout():void{verify_csrf();$_SESSION=[];session_destroy();header('Location: '.url());exit;} }
